insert into public.courses
    (code, name, hours, description, exclusions, breadth, prereq_tree)
values
    ('LCT249H1', 'Special Topics in Literature and Critical Theory', '24S', 'Studies in aspects of Literature and Critical Theory. Topics vary by instructor and are listed on the Victoria College programs website: https://vic.utoronto.ca/academic-programs/special-topics-courses/lct249h. Not offered every year.', null, 1, null::jsonb),
    ('LCT300Y0', 'Special Topics in Literature and Critical Theory', '48S', 'Special topic in Literature and Critical Theory. Topics vary by instructor and are listed on the Victoria College programs website: https://vic.utoronto.ca/academic-programs/special-topics-courses/lct300y.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('LCT301H1', 'Critical Writing Seminar', '24S', 'This course is a writing intensive class devoted to the practice and analysis of critical writing. We will explore the critical tradition, the public(s) for whom one writes, and the choice of voice, point of view, and writerly form. The class will be structured around workshop style discussion and writing exercises.', 'VIC301H1', 1, null::jsonb),
    ('LCT302H1', 'Pasts and Futures', '24S', 'An introduction to representations of history, in which we will consider concepts that turn on the problem of time such as tradition, periodization, genealogy, memory, crisis, revolution, eschatology, and utopia.', 'VIC302H1', 1, null::jsonb),
    ('LCT303H1', 'Memory and Trauma', '24S', 'This course will explore the problem of memory in relation to both collective and individual trauma. What pressure does trauma place on language, and agency, and how does it figure in commemoration, narrative, monumentalization, and other modes of representing the past?', 'VIC303H1', 2, null::jsonb),
    ('LCT304H1', 'Praxis and Performance', '24S', 'This course will explore what it means to “act” in cultural, political, religious, and psychological realms. We focus on the historically shifting relations between theory and practice, between artifice and agency, and between theatricality and spectatorship.', 'VIC304H1', 1, null::jsonb),
    ('LCT305H1', 'Institutions and Power', '24S', 'This course will consider some of the ideologies and practices of various institutions at work in the production and transmission of cultural objects and social power. These may include the family, museum, hospital, prison, university, library, and theatre, as well as fields such as publishing and religion.', 'VIC305H1', 1, null::jsonb),
    ('LCT306H1', 'Culture and Media', '24S', 'This course will consider relations between various cultural media – such as film, literature, photography, visual art, architecture – with specific attention to the historical demands and possibilities posed by technological change.', 'VIC306H1', 1, null::jsonb),
    ('LCT307H1', 'Periodization and Cultural History', '24S', 'This course explores the phenomenon of historical periodization in its various modes, including as a stylistic concept, a set of discursive norms for cataloguing and grouping cultural forms, and a means of organizing and contesting historical narratives.', 'VIC307H1', 2, null::jsonb),
    ('LCT308H1', 'Identities', '24S', 'Though “identity” might suggest sameness, it is historically unstable and has many components, including ability/disability, age, class, ethnicity, gender, health/illness, ‘race,’ sexuality, and religion. This course considers the complexities of identity-formation and identity-transformation as captured in literary texts and cultural artefacts over a wide range of historical and cultural contexts.', 'VIC308H1', 2, null::jsonb),
    ('LCT349H1', 'Special Topics in Literature and Critical Theory', null, 'Studies in aspects of Literature and Critical Theory. Topics vary by instructor and are listed on the Victoria College programs website: https://vic.utoronto.ca/academic-programs/special-topics-courses/lct349h. Not offered every year.', null, 1, null::jsonb),
    ('LCT401H1', 'Seminar in Comparative Literature', '24S', 'This course offers senior students in Literature and Critical Theory the opportunity to take part in a graduate seminar in Comparative Literature. Topics change annually and are listed on the Victoria College programs website.', null, 1, null::jsonb),
    ('LCT401Y1', 'Seminar in Comparative Literature', '48S', 'This course offers senior students in Literature and Critical Theory the opportunity to take part in a graduate seminar in Comparative Literature. Topics change annually and are listed on the Victoria College programs website.', null, 2, null::jsonb),
    ('LCT402H1', 'Translation and Comparativity', '24S', 'This course will consider questions of adaptation, appropriation, imitation, hybridity and incommensurability across languages, geographical regions, epochs, media, and academic disciplines. Course topics may include the role of translation in the historical projects of nation-building and empire.', 'VIC402H1', 2, '{"operator": "AND", "items": ["LCT202Y1", {"operator": "OR", "items": ["LCT302H1", "LCT303H1", "LCT304H1", "LCT305H1", "LCT306H1", "LCT307H1", "LCT308H1"]}]}'::jsonb),
    ('LCT403H1', 'Advanced Topics in Literature and Critical Theory', '24S', 'In-depth examination of selected issues in Literature and Critical Theory. Topics vary by instructor and are listed on the Victoria College programs website: https://vic.utoronto.ca/academic-programs/special-topics-courses/lct403h', null, null, '{"operator": "AND", "items": ["LCT202Y1", {"operator": "OR", "items": ["LCT302H1", "LCT303H1", "LCT304H1", "LCT305H1", "LCT306H1", "LCT307H1", "LCT308H1"]}]}'::jsonb),
    ('LCT494H1', 'LCT Senior Research Paper', null, 'This course provides an opportunity to design an interdisciplinary course of study, not otherwise available within the Faculty, with the intent of addressing specific topics in Literature and Critical Theory. Written application (detailed proposal, reading list and a letter of support from a Victoria College faculty member who is prepared to supervise) must be submitted for approval on behalf of Victoria College. For application procedures visit the Victoria College website. Not eligible for CR/NCR option.', 'VIC494H1', null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('LCT494Y1', 'LCT Senior Research Paper', null, 'This course provides an opportunity to design an interdisciplinary course of study, not otherwise available within the Faculty, with the intent of addressing specific topics in Literature and Critical Theory. Written application (detailed proposal, reading list and a letter of support from a Victoria College faculty member who is prepared to supervise) must be submitted for approval on behalf of Victoria College. For application procedures visit the Victoria College website. Not eligible for CR/NCR option.', 'VIC494Y1', null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('LIN101H1', 'Introduction to Linguistics: Sound Structure', '24L/12T', 'Introduction to fundamental principles of linguistics with particular attention to sound structure and its acquisition, processing, and variation; practice in elementary analytic techniques using data from a broad spectrum of languages.', 'LIN100Y1,  LIN101H5,  LINA01H3,  LINA02H3', 2, null::jsonb),
    ('LIN102H1', 'Introduction to Linguistics: Sentence Structure and Meaning', '24L/12P', 'Introduction to fundamental principles of linguistics with particular attention to sentence and meaning structure, their acquisition, processing, and variation; practice in elementary analytic techniques using data from a broad spectrum of languages.', 'LIN100Y1,  LIN102H5,  LINA01H3,  LINA02H3', 2, null::jsonb),
    ('LIN192H1', 'Sustaining Indigenous Languages', '24S', 'There has been much publicity in recent years about language shift and language loss and, along with it, language revitalization. In this course we examine shift involving Indigenous languages – and particularly those of Canada – from a variety of perspectives, and looking at reasons why one might want to ‘save’ a language. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('LIN193H1', 'African Languages and Language-based Music', '24L', 'The connection between language and music is one of the oldest debates in the history of humanity. In this course, we will explore this issue by surveying African languages and language-based music (e.g., talking drums, xylophones, singing, and chants). Students will learn about the building blocks of human language and the linguistic features unique to African languages. We will focus on how various African cultures communicate by transposing linguistic features to musical melodies and how listeners comprehend this musical code. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('LIN194H1', 'The Science Behind Our Accents', '24P', 'When we speak, the sound is transmitted through the air as a complex sound wave. How are various speech sounds – vowels and consonants – manifested acoustically? What does it mean, in physical terms, to have an accent? These and other related questions will be explored through computer-based acoustic analysis and perceptual experimentation. Upon completion of this course, students will (i) have overview knowledge of basic acoustic properties characterizing phonetic variation pertaining to speech, and accents in particular, (ii) be able to conduct simple speech production and perception experiments, and write up results in the form of scientific research reports, (iii) begin to read and understand scientific literature pertaining to acoustic phonetic variation and its relevance for communication. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('LIN195H1', 'Babel: Language in the Mind of Speakers', '24L', 'What is the relation between language and thought? In this course we examine how language is represented in our minds, and how language and cognitive processes interact. While the link between words and meanings is arbitrary and reflects culture, language is considered to be a universal property of our species. We will examine the place of language in the architecture of the mind; the debates about the universality of language structure vs. linguistic relativism; and how language and thought interact in children’s development. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('LIN196H1', 'Language and Communication', '24L', 'We will explore the ways in which information is communicated in conversation. We will consider systematic ways in which what a speaker intends to communicate with language goes beyond what one says in conversation. The goal of the course is to investigate the ways in which speakers rely on knowledge of language and implicit “rules” to enrich and transform the literal content of someone’s utterance. Students will familiarize themselves with some fundamental concepts in linguistic semantics and pragmatics. They will develop analytic skills necessary to analyze a text in an academic context and beyond. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('LIN197H1', 'Language and Social Justice', '24L', 'This course explores how language is used to construct and reinforce unjust social structures. Topics may include: the underlying sexism, classism, racism, and ableism of prestige dialects and prescriptive language education; the history and consequences of national language movements; language endangerment, documentation, and revival; sign languages and language rights for the deaf and hard-of-hearing; popular media representations of linguistic variation, especially vocal fry, uptalk, and regional accents; and the relationships between language and sex, gender identity, and sexuality. Students will develop research, analytic, and writing skills through critique and discussion of assigned texts, independent research projects, and regular written and oral presentation of their work. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('LIN198H1', 'Language Diversity', '24L', 'There are estimated to be about 7000 languages currently spoken in the world. What do they have in common? In what ways are they different? This course will explore these questions, covering such topics as meaning, sound systems, the structure of words, the order of words in sentences, question formation, concepts such as subject and object, tense systems, pronoun systems. We will also discuss language loss and revival. Students will develop analytic skills as they consult published grammars and other resources to address these issues. Students will share their findings through oral and written presentation. Examples will be drawn from a wide range of languages. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('LIN199H1', 'Exploring Heritage Languages', '24L', 'We will explore how speakers use Heritage Languages in Toronto, using data recently collected in the GTA, so students should be familiar with one of these languages. We will collect, organize and interpret information about heritage languages in Toronto. We will look for speech patterns that differentiate first, second and third generation speakers in Toronto from corresponding speakers in their countries of origin, and look at the effects of cultural and language attitudes and usage. Students will develop analytic skills as they explore a range of research methods and resources to address these issues. Students will share their findings through oral and written presentation, including online formats. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('LIN200H1', 'Introduction to Language', '24L/12T', 'Introduction to Language is a general-interest course on language. Possible topics include: the structure of language; how language changes over time, the social and psychological aspects of language, language and culture, the origin of language, writing systems, and language acquisition. (This course does not count towards the Linguistics minor, major, or specialist programs.)', 'LIN100Y1,  LIN101H1,  LIN102H1,  LIN101H5,  LIN102H5,  LINA01H3,  LINA02H3,  LIN200H5', 2, null::jsonb),
    ('LIN201H1', 'Canadian English', '24L', 'A study of English spoken in Canada. Topics include: vocabulary items, usage surveys, non-standard dialect enclaves, regional variation and historical development. Students will develop original research projects in linguistics.', null, 2, '{"operator": "OR", "items": [{"operator": "AND", "items": ["LIN101H1", "LIN102H1"]}, "LIN200H1"]}'::jsonb),
    ('LIN202H1', 'Introduction to Indigenous Languages of the Americas', '24L', 'This is an introduction to Indigenous languages and cultures of Central, North, and South America. Students will be exposed to discussions about what is an indigenous language, social status of indigenous languages as well as indigenous movements towards language documentation and revitalization and language education in the Americas.', null, 2, null::jsonb),
    ('LIN203H1', 'English Words', '24L/12T', 'English has a rich vocabulary. We will learn how it has developed over time, and investigate aspects of the meaning and pronunciation of words. Most of all, we will study how words are put together, so that students will be able to recognize and analyze unfamiliar words. (This course does not count for the Linguistics major or specialist programs).', 'LIN203H5,  LIN233H5', 2, null::jsonb),
    ('LIN204H1', 'English Grammar', '24L/12T', 'How the English language works: students analyze a wide variety of English grammatical structures and learn how they vary across dialects and change through time. (This course does not count towards the Linguistics major or specialist programs).', 'LIN204H5,  LINB18H3', 2, null::jsonb),
    ('LIN206H1', 'Languages of the World', '24L/12T', 'This course is a survey of languages and language families around the world. The course focuses on their linguistic similarities and differences, as well as their historical and social relationships. Course content will be explored through individual and comparative analysis of the linguistic structures of a representative sample of languages. (This course does not count towards the Linguistics major or specialist programs.)', null, 2, null::jsonb),
    ('LIN207H1', 'Language and Technology', '24L/12T', 'This course is a survey of the history and nature of language technologies, from the emergence of writing in ancient civilizations to modern large language models. Topics may include literacy, mechanized speech, speech recognition, machine translation, large language models, generative pre-trained transformers, and the ethics of language technologies. Note that this is not a computational linguistics course and does not cover the mathematical foundations or computational implementation of language models in any depth. The focus of this course is on the historical development of language technologies and their relationship to natural languages, language communities, and the field of linguistics. (This course does not count towards the Linguistics major or specialist programs.)', null, 2, null::jsonb),
    ('LIN208H1', 'Linguistic Discrimination and Justice', '24L/12T', 'This course explores the relationship between language and unjust social structures and practices, with a focus on discrimination against users of particular language varieties. A key component of the course is understanding and practicing methods from the field of sociolinguistics to identify and combat linguistic discrimination, contextualized through discussion of examples from multiple languages and communities. Topics may include dialect discrimination, language ideologies, language and the law, linguistic colonialism, language rights, prescriptivism, slurs and linguistic abuse, language and gender, and audism. (This course does not count towards the Linguistics major or specialist programs.)', null, 2, null::jsonb),
    ('LIN211H1', 'American Sign Language 1', '36L', 'This course is an introductory language course for students with little or no prior knowledge of American Sign Language (ASL). It provides an immersive introduction to ASL, with a focus on basic vocabulary, grammar, conversation, and appropriate behaviours for everyday interactions in a variety of social situations. The language is taught through various immersive activities, such as lecture/discussion, interactive games, and situational conversations, supplemented with readings and videos. A significant emphasis throughout the course is placed on Deaf culture and issues facing the Deaf community. (This course does not count towards the Linguistics minor, major, or specialist programs).', null, 2, null::jsonb),
    ('LIN212H1', 'American Sign Language 2', '36L', 'This course is an introductory language course for students with minimal prior knowledge of American Sign Language (ASL). It builds on the knowledge and skills gained in American Sign Language 1 and further immerses students in the language, literature, culture, and community associated with ASL. Additionally, it offers students opportunities to enhance their comprehension and production skills through content-specific conversations and interactive activities that utilize accurate ASL vocabulary, classifiers, phrases, grammatical structures, and non-manual markers across different contexts and purposes. (This course does not count towards the Linguistics minor, major, or specialist programs).', null, 2, '{"operator": "AND", "items": ["LIN211H1"]}'::jsonb),
    ('LIN228H1', 'Phonetics', '24L/12T', 'Phonetics is a linguistics course that investigates the sounds most commonly used in languages from an articulatory and acoustic point of view, with practice in their recognition and production. Students will learn the International Phonetic Alphabet (IPA) and practice transcribing a wide variety of speech sounds.', 'LIN228H5,  LINB09H3', 2, null::jsonb),
    ('LIN229H1', 'Phonological Patterns in Language', '24L/12T', 'The nature and organization of phonological systems, with practical work in linguistic analysis.', 'LIN229H5,  LINB04H3', 2, '{"operator": "AND", "items": ["LIN101H1", "LIN228H1"]}'::jsonb),
    ('LIN232H1', 'Syntactic Patterns in Language', '24L/12T', 'The nature and organization of syntactic systems; their relation to semantic systems and the linguistic organization of discourse; practical work in linguistic analysis.', 'LIN232H5,  LINB06H3', null, '{"operator": "AND", "items": ["LIN102H1"]}'::jsonb),
    ('LIN241H1', 'Introduction to Semantics', '24L/12T', 'An introduction to meaning within linguistics and the interpretation of language in context. Topics include logical and semantic relations, pragmatic concepts such as presupposition and implicature, the nature of thematic roles, quantifiers and scope relations, the expressions of temporal and modal relations in natural language.', 'LIN237H5,  LIN247H5,  LINC12H3,  FREC12H3', 2, '{"operator": "AND", "items": ["LIN102H1"]}'::jsonb),
    ('LIN251H1', 'Introduction to Sociolinguistics', '24L/12T', 'How does linguistic variation construct identity? Introduction to recent sociolinguistic literature on language contact, multilingualism, code-switching, expressions of ethnic solidarity and regional identity, sex and gender differentiation, dialect geography, sociophonetics, perceptual dialectology, diffusion of norms in mobile populations, documentation of variation in lesser studied languages, and changes across the life-span.', 'LIN256H5,  LINB20H3', 2, '{"operator": "AND", "items": ["LIN101H1", "LIN102H1"]}'::jsonb),
    ('LIN299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('LIN299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('LIN302H1', 'South American Indigenous Languages', '36L', 'This course is an overview of linguistic diversity in South America, centred on Brazilian indigenous languages and peoples. Students will be introduced to current practices in the maintenance and revitalization of Brazilian indigenous languages and current strategies for empowering indigenous peoples (such as training indigenous filmmakers and music production). We will study aspects of the grammar of Brazilian languages through the analysis of small data sets, and we will discuss the influence of Brazilian indigenous languages on Brazilian Portuguese. Not offered every year.', 'LIN303H1,  PRT368H1', 2, '{"operator": "OR", "items": [{"operator": "AND", "items": ["LIN101H1", "LIN102H1"]}, "LIN200H1", "ANT253H1"]}'::jsonb),
    ('LIN303H1', 'Central American Indigenous Languages', '36L', 'This course is about indigenous languages of Central America, focusing on Mayan languages and culture. Students will be introduced to current movements in the maintenance and revitalization of indigenous languages and current strategies for empowering indigenous people (such as training indigenous linguists, music production in indigenous languages, and intercultural bilingual education). Students will also study grammatical features of indigenous languages through the analysis of small data sets, and discuss the contact between indigenous languages and Spanish. Not offered every year.', 'LIN302H1', 2, '{"operator": "OR", "items": [{"operator": "AND", "items": ["LIN101H1", "LIN102H1"]}, "LIN200H1", "ANT253H1"]}'::jsonb),
    ('LIN305H1', 'Quantitative Methods in Linguistics', '36L', 'Principles of research design, data collection, and a wide variety of statistical techniques for research in various subfields of linguistics.', 'LIN318H5,  LINB29H3', 2, '{"operator": "AND", "items": ["LIN101H1", "LIN102H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('LIN306H1', 'Language Diversity and Language Universals', '24L', 'This linguistics course examines cross-linguistic typological features found in the languages of the world. Special attention is given to describing morphological and syntactic patterns found cross-linguistically. The goal of the course is to draw on the diversity of languages in order to uncover language universals. (Not offered every year)', 'LIN476H5,  LINC13H3', 2, '{"operator": "AND", "items": ["LIN232H1"]}'::jsonb),
    ('LIN322H1', 'Phonological Theory', '36L', 'Basic issues in current phonological theory. Problems focusing on analysis and theory. (Students who want to pursue graduate studies in linguistics are strongly advised to include this course in their program.)', 'LIN322H5,  LIN329H5,  LINC02H3', 2, '{"operator": "AND", "items": ["LIN229H1"]}'::jsonb),
    ('LIN323H1', 'Acoustic Phonetics', '24L', 'This linguistics course is an introduction to the acoustic phonetics of the vocal tract, including acoustic properties of speech and its analysis using instrumental techniques.', 'LIN328H5', 5, '{"operator": "AND", "items": ["LIN101H1", "LIN102H1", "LIN228H1"]}'::jsonb),
    ('LIN331H1', 'Syntactic Theory', '36L', 'A course in syntactic theory and analysis within a current formal framework. (Students who want to pursue graduate studies in linguistics are strongly advised to include this course in their program.)', 'LIN332H5,  LINC11H3', 2, '{"operator": "AND", "items": ["LIN232H1"]}'::jsonb),
    ('LIN333H1', 'Morphological Patterns in Language', '36L', 'The nature and organization of morphological systems, with practical work in linguistic analysis.', 'LIN231H5,  LINB10H3', 2, '{"operator": "AND", "items": ["LIN229H1", "LIN232H1"]}'::jsonb),
    ('LIN341H1', 'Semantic Theory', '36L', 'This linguistics course focuses on the study of natural language semantics and the relation between interpretation and syntactic structure. Topics include predication and quantification, scope and anaphora, problems of discourse analysis, the interpretation of different types of pronouns, and ellipsis.', null, 2, '{"operator": "AND", "items": ["LIN241H1"]}'::jsonb),
    ('LIN351H1', 'Sociolinguistic Patterns in Language', '24L/12T', 'In this sociolinguistics course, we explore linguistic variation and its social implications, especially the quantitative study of phonological and grammatical features and their correlations with age, sex, ethnicity, and other social variables.', null, 3, '{"operator": "AND", "items": ["LIN251H1"]}'::jsonb),
    ('LIN362H1', 'Historical Linguistics', '24L', 'An introduction to diachronic linguistics. Theories of language change; the comparative method, internal reconstruction, linguistic geography, the origin of languages; language death.', 'LIN360H5', 2, '{"operator": "AND", "items": ["LIN229H1"]}'::jsonb),
    ('LIN398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('LIN398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('LIN399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('LIN399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('LIN402H1', 'Linguistic Typology and Constructed Languages', '36L', 'This course uses constructed languages (e.g., Esperanto, Klingon, Dothraki) to explore crosslinguistic patterns in language structure. Topics include phonological and morphosyntactic typology, language change over time, effects of culture and environment on language, history of language construction, standards in writing descriptive grammars, and critical analysis of research on language diversity.', null, 2, '{"operator": "AND", "items": ["LIN228H1", "LIN229H1", "LIN232H1", "LIN241H1", "LIN251H1", {"operator": "OR", "items": ["LIN322H1", "LIN331H1"]}]}'::jsonb),
    ('LIN405H1', 'Advanced Quantitative Methods in Linguistics', '36L', 'This course introduces advanced statistical modeling techniques using the statistical software R, tailored specifically to the needs of linguistic research.', null, 2, '{"operator": "AND", "items": ["LIN305H1"]}'::jsonb),
    ('LIN409H1', 'Structure of a Specific Language', '24L', 'Topics may include: the phonological, morphological, syntactic, and semantic systems; the writing system; a brief diachronic sketch; linguistic variation and sociolinguistic aspects. (Not offered every year).', 'LIN479H5 or  LINC61H3 if the same language was analyzed.', 2, '{"operator": "AND", "items": ["LIN228H1", "LIN229H1", "LIN232H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('LIN423H1', 'Phonetic Analysis', '36S', 'This course provides students with hands-on experience with main methods of linguistic phonetic (acoustic and articulatory) analysis through project-based group work and training in writing up experimental results.', 'LIND09H3', 5, '{"operator": "AND", "items": ["LIN323H1"]}'::jsonb),
    ('LIN429H1', 'Research in Phonology', '24S', 'Research in Phonological Theory, including guided instruction in how to undertake critical reading of primary literature, develop an original topic, write a research paper, an abstract, a handout, and give an oral presentation. Not eligible for CR/NCR option.', null, 2, '{"operator": "AND", "items": ["LIN322H1"]}'::jsonb),
    ('LIN432H1', 'Advanced Morphology', '24L', 'Current research involving morphology, including the role of morphology in the grammar, the nature of inflectional paradigms, affixes affecting grammatical relations constitute this linguistics course. Each year one topic will be a special focus and will be dealt with at length. (Not offered every year)', null, 2, '{"operator": "AND", "items": ["LIN333H1"]}'::jsonb),
    ('LIN439H1', 'Research in Syntax', '24S', 'Research in Syntactic Theory, including guided instruction in how to undertake critical reading of primary literature, develop an original topic, write a linguistics research paper, an abstract, a handout, and give an oral presentation. Not eligible for CR/NCR option. (Not offered every year)', null, 2, '{"operator": "AND", "items": ["LIN331H1"]}'::jsonb),
    ('LIN441H1', 'Advanced Semantics and Pragmatics', '24S', 'This course covers current research in formal semantics and pragmatics. Topics may vary from year to year. The course is intended to be a seminar-style course; it includes reading primary literature and writing a research paper.', null, 2, '{"operator": "AND", "items": ["LIN341H1"]}'::jsonb),
    ('LIN451H1', 'Urban Dialectology', '24L', 'Ways in which urban sub-cultures differ in their use of language. How speakers dialects reflect their ethnicity, group affiliation, and other social categories. Practice in dialect analysis based on data from the speech community, emphasizing procedures and techniques.', null, 3, '{"operator": "AND", "items": ["LIN351H1", {"credits": 2.0, "department": null}]}'::jsonb),
    ('LIN456H1', 'Language Variation and Change: Theory and Analysis', '36L', 'The theory and practice of sociolinguistics. The inter-relationship between language and society from the perspective of collecting, organizing, and analyzing patterns in natural speech data, including field methods and quantitative methods for correlating linguistic and social variables.', 'LIN458H5', 3, '{"operator": "AND", "items": ["LIN351H1"]}'::jsonb),
    ('LIN458H1', 'Revitalizing Languages', '24L', 'A study of language endangerment and language revitalization efforts. The languages of focus will vary from year to year, depending on the instructor. Topics include language classification and a survey of major features of the languages, what it means for a language to be endangered, the factors that contribute to language shift, and efforts to reverse language shift, including discussion of literacy, documentary linguistics and dictionaries.', null, 3, '{"operator": "AND", "items": ["LIN101H1", "LIN102H1", {"credits": 2.0, "department": null}]}'::jsonb),
    ('LIN481H1', 'Introduction to Analysis and Argumentation', '36L', 'Linguistic argumentation, practice in constructing and evaluating hypotheses, and critical evaluation of representative articles. Emphasis on the structure of arguments rather than on the analysis of a particular language.', 'LIN411H5,  LINC10H3', 2, '{"operator": "OR", "items": ["LIN322H1", "LIN331H1"]}'::jsonb),
    ('LIN490H1', 'Special Topics in Linguistics', '24S', 'A specific topic in linguistics will be explored in depth in Special Topics in Linguistics. Students will learn about a narrowly-focused area of linguistics, including guided instruction in how to undertake critical reading of primary literature, develop a research topic and write a linguistics research paper. Not eligible for CR/NCR option. (Not offered every year)', null, 2, '{"operator": "AND", "items": [{"credits": 2.0, "department": "LIN"}, {"credits": 1.0, "department": "LIN"}]}'::jsonb),
    ('LIN495Y1', 'Individual Project', null, 'A research or reading project in linguistics undertaken by the student under the supervision of a staff member. Open only when a faculty member is willing and available to supervise. Students are required to submit an application to the department by the first day of classes or earlier (preferred). Not eligible for CR/NCR option.  Application found at https://www.linguistics.utoronto.ca/undergraduate/curriculum-course-information/research-opportunities-and-independent-studies.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 3.0, "department": null}]}'::jsonb),
    ('LIN496H1', 'Individual Project', null, 'A research or reading project in linguistics undertaken by the student under the supervision of a staff member. Open only when a faculty member is willing and available to supervise. Students are required to submit an application to the department by the first day of classes or earlier (preferred). Not eligible for CR/NCR option.  Application found at https://www.linguistics.utoronto.ca/undergraduate/curriculum-course-information/research-opportunities-and-independent-studies.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 3.0, "department": null}]}'::jsonb),
    ('LIN497Y1', 'Individual Project', null, 'A research or reading project in linguistics undertaken by the student under the supervision of a staff member. Open only when a faculty member is willing and available to supervise. Students are required to submit an application to the department by the first day of classes or earlier (preferred). Not eligible for CR/NCR option.  Application found at https://www.linguistics.utoronto.ca/undergraduate/curriculum-course-information/research-opportunities-and-independent-studies.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 3.0, "department": null}]}'::jsonb),
    ('LIN498H1', 'Individual Project', null, 'A research or reading project in linguistics undertaken by the student under the supervision of a staff member. Open only when a faculty member is willing and available to supervise. Students are required to submit an application to the department by the first day of classes or earlier (preferred). Not eligible for CR/NCR option.  Application found at https://www.linguistics.utoronto.ca/undergraduate/curriculum-course-information/research-opportunities-and-independent-studies.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 3.0, "department": null}]}'::jsonb),
    ('LIN499H1', 'Individual Project', null, 'A research or reading project in linguistics undertaken by the student under the supervision of a staff member. Open only when a faculty member is willing and available to supervise. Students are required to submit an application to the department by the first day of classes or earlier (preferred). Not eligible for CR/NCR option. Application found at https://www.linguistics.utoronto.ca/undergraduate/curriculum-course-information/research-opportunities-and-independent-studies.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 3.0, "department": null}]}'::jsonb),
    ('LMP200H1', 'Pathobiology of the Cell', '24L/12T', 'This course builds on concepts in cellular pathobiology to develop an advanced understanding of the function and dynamics of the cell in the context of health and disease. Concepts in cell injury, cell adaptation, migration, cell stress, cell survival, cell death, oxidative stress, endocytosis, ion homeostasis, protein folding, and their implications for disease are covered.', 'LMP301H1,  LMP363H1,  LMP340H1', 4, '{"operator": "AND", "items": ["BIO230H1", "PSL300H1"]}'::jsonb),
    ('LMP299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('LMP299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('LMP301H1', 'Introduction to the Biochemistry of Human Disease', '24L', 'Introduces concepts and mechanisms of disease processes as they arise from disturbances of normal biochemical and physiological functions. The rational use of the clinical biochemistry laboratory in the diagnosis and management of disease is explained. Not intended for students in the Pathobiology Specialist program.', 'LMP310H1,  LMP320H1', 4, '{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}'::jsonb),
    ('LMP305Y1', 'Pathobiology Research Analysis and Project', '24L/100P', 'This course is designed to introduce third-year students to biomedical research, and to provide them with the analytical skills required to be a successful scientist. Students will have the opportunity to carry out a full-year research project under the supervision of an LMP faculty member (6-8 hours/week in lab). A lecture component will cover laboratory practice, experimental design, basic logic/argument, statistics, data analysis and scientific communication. The fundamentals taught in these lectures will be used to critique and analyze scientific literature. This course is recommended for students with a general interest in research and especially to students who will conduct additional research projects as part of the LMP summer research program and/or the  LMP405Y1 fourth-year research project course.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["STA288H1", "STA220H1"]}, "BCH210H1", "BIO230H1"]}'::jsonb),
    ('LMP310H1', 'Fundamentals of Pathobiology', '24L/12T', 'This course covers the major molecular mechanisms that impact human health and disease. Specifically, it is divided into three blocks that focus on the fundamentals of pathobiology in cancer, cardiovascular diseases and infection. It is intended to introduce the cellular and molecular concepts of health and disease that will be explored with more depth in fourth-year LMP courses.', null, 4, '{"operator": "AND", "items": ["LMP200H1", "BCH210H1"]}'::jsonb),
    ('LMP320H1', 'Pathobiology of Stem Cells', '24L/12T', 'This course introduces stem cells and their impact on human health and disease. Stem cells are studied from the perspective of development and disease, with a focus on the nervous system, respiratory system and cancer. This course is intended to provide a foundation in the basis of stem cells in preparation for fourth-year courses.', null, 4, '{"operator": "AND", "items": ["LMP200H1"]}'::jsonb),
    ('LMP330H1', 'Genetic and Computational Modeling in Human Development and Disease', '24L/12T', 'Introduces the use and impact of genetic model systems and organisms in exploring aspects of human reproduction, development, aging and disease. Ethical issues in animal research, genetic manipulation, and disease modeling are highlighted. This course also introduces the bioinformatics concepts and methods used in biological data analysis.', 'LMP408H1', 4, '{"operator": "AND", "items": ["LMP200H1", {"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}]}'::jsonb),
    ('LMP363H1', 'Principles of Pathobiology', '24L', 'Pathological changes brought on by foreign compounds; mechanisms of pathologic, toxic and carcinogenic change.', 'LMP310H1,  LMP320H1', 4, '{"operator": "AND", "items": ["BIO230H1", {"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}]}'::jsonb),
    ('LMP399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('LMP399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('LMP405Y1', 'Project in Pathobiology', '154P', 'A self-contained research project to be completed under the supervision of a faculty member. The main areas of research are as listed in the Department''s section of the Academic Calendar. The student will normally have completed three full years of study, and is expected to devote at least one full day per week to the project. Admission is by arrangement with the Department and with a particular supervisor. A list of potential supervisors is available from the Departmental Office and on our web site. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}, "LMP310H1", "LMP320H1", "LMP330H1"]}'::jsonb),
    ('LMP410H1', 'Pathobiology of Neurodegenerative Disease', '24L', 'Molecular basis of neurodegenerative diseases of the central and peripheral nervous systems. Emphasis on the molecular pathobiology of neurodegenerative diseases, current research developments and guidance with writing of research proposals. Mid-term and final exams will practice assembly of a succinct research proposal and query neurodegenerative disease material taught in course.', null, 4, '{"operator": "OR", "items": ["BCH311H1", {"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}]}'::jsonb),
    ('LMP415H1', 'Forensic Pathobiology', '24L', 'A thematic review of the major scientific areas and research controversies in forensic medicine. The approach is mechanistic analysis and evidence-based medicine. Classical forensic medicine is critically analyzed with emphasis on experimental methods to resolve controversies. We also explore how the justice system utilizes medical and scientific data.', null, 4, '{"operator": "AND", "items": ["LMP310H1", "LMP320H1"]}'::jsonb),
    ('LMP420H1', 'Cancer Pathogenesis', '24L/12T', 'A general introduction to the cellular and molecular aspects of cancer and its etiology. Topics include pathophysiology of cancer, invasion and metastases, role of the immune system, immune evasion, understanding biological targets, chemotherapeutic and immunotherapeutic agents and its mechanism of action, and resistance mechanisms of cancer.', null, 4, '{"operator": "AND", "items": ["LMP310H1"]}'::jsonb),
    ('LMP430H1', 'Metabolic Disorders', '24L/12T', 'This is an advanced-level course that focuses on the pathobiology of metabolic disorders, whether inherited or acquired. It covers enzymatic pathways and diseases associated with fat/energy metabolism, dyslipidemia, dysglycemia, aminoacidopathies and lysosomal storage disorders.', null, 4, '{"operator": "AND", "items": ["BCH210H1", "PSL300H1"]}'::jsonb),
    ('LMP440H1', 'Mechanisms in Host-Microbe Interactions', '24L', 'Mechanisms that allow microbial pathogens to cause disease and the host to detect infection, mount an inflammatory response and resolve the infection. Primary research articles are discussed. Topics include commensal and pathogenic bacteria, microbe recognition, programmed cell death, immunometabolism, inflammatory diseases.', 'LMP402H1,  LMP436H1', 4, '{"operator": "OR", "items": [{"operator": "AND", "items": ["IMM340H1", "IMM350H1"]}, {"operator": "AND", "items": ["IMM341H1", "IMM351H1"]}, {"operator": "AND", "items": ["MGY377H1", "MGY378H1"]}, "LMP310H1"]}'::jsonb),
    ('LMP450H1', 'Organogenesis in Health and Disease', '24L/12T', 'This course introduces advanced topics in stem cell biology and focuses on the latest developments related to the use of stem cells in the design and generation of organoids and organs for use in research. The use of organogenesis within basic and clinical research settings will be highlighted with a focus on several human diseases. This course will build on the third-year courses, through which students will have been introduced to stem cell biology within the context of human diseases.', null, 4, '{"operator": "AND", "items": ["LMP320H1", "LMP330H1"]}'::jsonb),
    ('LMP460H1', 'Pathobiology of the Cardiovascular System', '24L', 'Pathobiology of the heart, blood vessels, and lymphatic system. Congenital diseases of the heart, ischemic injury, stroke. Treatments of vascular disease and cardiovascular biomaterials. Major focus on atherosclerosis and hypertension. The emphasis is on the underlying cell biology of these processes.', 'LMP406H1', 4, '{"operator": "OR", "items": [{"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}, "PSL302Y1"]}'::jsonb),
    ('MAT133Y1', 'Calculus and Linear Algebra for Commerce', '72L', 'Mathematics of finance. Matrices and linear equations. Review of differential calculus; applications. Integration and fundamental theorem; applications. Introduction to partial differentiation; applications. Course material expects at minimum high school calculus has been completed prior to undertaking course. This course will be useful for students interested in learning applied calculus in relation to future studies in commerce and/or social science programs.', 'MAT133Y5/ ( MATA32H3,  MATA33H3)', 5, null::jsonb),
    ('MAT135H1', 'Calculus I', '36L/12T', 'In this first introduction to Calculus, students will be introduced to the tools of differential calculus, the branch of calculus that is motivated by the problem of measuring how quantities change. Students will use these tools to solve other problems, including simplifying functions with straight lines, describing how different types of change are related, and computing maximum and minimum quantities. This course will focus on developing a deep understanding of why the tools of calculus make sense and how to apply them to the social, biological, and physical sciences. It will also emphasize translating between algebraic, graphical, numerical and verbal descriptions of each concept studied. This course will be useful for students interested in learning applied calculus in relation to future studies in economics, life science, and physical and mathematical science programs. The following concepts will be studied: Limits, asymptotes, continuity, derivatives, linear approximation of functions, the notion of a differential equation (DE) and a solution of a DE, slope fields, and Euler''s method.', 'MAT135H5/  MAT136H5/  MATA30H3/  MATA31H3/  MATA36H3/ APS162H1/ APS163H1/ ESC194H1/ ESC195H1/ MAT186H1/ MAT187H1/ MAT196H1/  MAT197H1', 5, null::jsonb),
    ('MAT136H1', 'Calculus II', '36L/12T', 'This second part of the introductory Calculus sequence focuses on integral calculus beginning with the Fundamental Theorem of Calculus, the connection between two seemingly unrelated problems: measuring changing quantities and finding areas of curved shapes. Students will develop a deep understanding of the integral, and use it to: unpack equations involving derivatives; to make sense of infinite sums; to write complicated functions as ''infinite polynomials''; and to compute areas, volumes, and totals in applied problems. This course will further develop students'' abilities to translate between algebraic, graphical, numerical, and verbal descriptions of mathematics in a variety of applied contexts. This course is a continuation of  MAT135H1 and will be useful for students interested in learning applied calculus in relation to future studies in economics, life science, and physical and mathematical science programs. The following concepts will be studied: Integration, basic techniques of integration (substitution and by parts), improper integrals, using computer algebra systems (CAS) for integration, Taylor polynomials and Taylor series, ratio test for power series, radius of convergence of power series, first-order differential equations and systems of differential equations: modelling, separable DEs, and using CAS to study and find solutions.', 'MAT136H5/  MATA36H3/ APS163H1/ ESC195H1/ MAT187H1/  MAT197H1', 5, '{"operator": "OR", "items": ["MAT135H1", "MAT135H5", "APS162H1", "ESC194H1", "MAT186H1", "MAT196H1"]}'::jsonb),
    ('MAT137Y1', 'Calculus with Proofs', '72L/24T', 'A conceptual approach for students interest in theoretical foundations of mathematics. Attention is given to computational aspects as well as problem-solving techniques. Limits and continuity, mean value theorem, elementary transcendental functions including trigonometric functions, inverse function theorem, differentiation, integration, fundamental theorem of calculus, Taylor''s theorem, sequences and series, power series, and applications. This course will be useful for students interested in learning theoretical calculus and proofs in relation to future studies in computer science, economics, mathematics, physics, and statistics.', 'MAT137Y5/ ( MAT137H5,  MAT139H5)/ ( MATA30H3/  MATA31H3,  MATA37H3)', 5, null::jsonb),
    ('MAT138H1', 'Introduction to Proofs', '36L/12T', 'The goal of this course is for students to become comfortable with abstraction, rigour, logic, and proofs. They will practice reading and understanding mathematical statements, analyzing definitions and properties, formulating conjectures and generalizations, providing and writing reasonable and precise arguments, writing and critiquing proofs. The instructor may use specific mathematical content, which could vary from year to year, to practice these skills. Students who take  MAT135H1 and  MAT136H1 and wish to take  MAT237Y1 are required to take  MAT138H1 prior to undertaking  MAT237Y1. Students who are taking  MAT137Y1 or  MAT157Y1 and/or  MAT240H1 and are interested in more preparation with logical arguments are encouraged to take  MAT138H1 concurrently.', 'MAT137Y1/  MAT137Y5/ ( MAT137H5,  MAT139H5)/ ( MATA30H3/ MATA31H3,  MATA37H3)/  MAT157Y1/  MAT157Y5', 5, null::jsonb),
    ('MAT157Y1', 'Analysis I', '72L/48T', 'A theoretical course in calculus; emphasizing proofs and techniques. Elementary logic, limits and continuity, least upper bounds, intermediate and extreme value theorems. Derivatives, mean value and inverse function theorems. Integrals, fundamental theorem, elementary transcendental functions. Techniques of integration. Taylor''s theorem; sequences and series; uniform convergence and power series. This course is required for the Mathematics Specialist, the Applied Mathematics Specialist, the Mathematics and Physics Specialist, and the Mathematics and Philosophy Specialist program and provides a strong theoretical mathematics background.', 'MAT157Y5/ ( MAT157H5,  MAT159H5)', 5, null::jsonb),
    ('MAT192H1', 'Mathematics and Art', '36L', 'This course will explore the various bridges between Mathematics and Art. We will combine exploration of mathematical concepts with the artistic visualization of those concepts through a range of mediums, including fine art, architecture, origami, textile, fiber art, dance and movement, craft, and digital art. We will investigate the potential of mathematics to generate visually appealing objects that reveal some of the structure of the underlying mathematics. On the flip side, we study existing artworks from a mathematical vantage point to uncover new aspects of their beauty. One of the main goals of the course is to open a new window to process mathematical concepts and to link the creative processes inherent in both mathematics and the arts.  Along the way students develop insight into the diversity and overarching nature of mathematics as well as an intuitive understanding of concepts such as numerical sequences, Euclidean geometry, tiling, fractals, platonic solids, hyperbolic geometry, and topology. This course is a combination of theory and hands on activities. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('MAT193H1', 'Women''s Mathematics', '36S', 'Mathematics has been shaped in significant ways by the work of outstanding female mathematicians such as Hypatia, Emmy Noether, Sofia Kovalevskaya, and Maryam Mirzakhani. Despite these successes, women still experience barriers to entering the field and participating at the highest levels. This course will blend an exploration of mathematics created by women with a study of the issue of women in mathematics. Students will have the opportunity to examine the complex factors that impact women''s participation in STEM, learn about the lives of female mathematicians, create their own mathematics, and sharpen their spatial cognition and logical thinking skills. Restricted to first-year students. Not eligible for CR/NCR option.', 'Not intended for students in a Mathematics Specialist or Major program.', 5, null::jsonb),
    ('MAT194H1', 'Mathematical Personalities', '24L', 'An in-depth study of the life, times and work of several mathematicians who have been particularly influential. Examples may include but are not limited to: Coxeter, Euler, Germain, Grothendieck, Hilbert, Kovalevskaya, Kowalewski, Mirzhakhani, Newton, Noether, Ramanujan. Not intended for students in a Mathematics Specialist or Major program. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('MAT195H1', 'Mathematics as an Interdisciplinary Pursuit', '24L', 'A study of the interaction of mathematics with other fields of inquiry: how mathematics influences, and is influenced by, the evolution of science and culture. Art, music, and literature, as well as the more traditionally related areas of the natural and social sciences may be considered. Not intended for students in a Mathematics Specialist or Major program. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('MAT197H1', 'Mathematics as a Recreation, Mathematical Discovery and Creative Problem Solving', '24L', 'This course is an exploration into the creative process and use of imagination as they arise in the context of mathematical problem solving, puzzles, and recreational mathematics. The topics for the course may include a study of games, puzzles and problems that require a pre-Calculus background. One of the course''s main goals is to hone each participant''s creativity and mathematical problem-solving skills while guiding them towards the ''Aha!'' experience which accompanies independent discovery. Not intended for students in Mathematics Specialist or Major programs. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('MAT198H1', 'Cryptology: The Mathematics of Secrecy and Security', '24S', 'How do we send our own confidential information through secure channels, and how can we break codes to uncover the secret information of our adversaries? The mathematical field of cryptology is dedicated to answering such questions. In this course we will study breakthroughs in cryptology, from secret messages in the ancient world and the Enigma cipher in World War II, to modern cryptosystems that facilitate online commerce. Along the way, you will develop a sophisticated understanding of how numbers interact and develop the ability to communicate messages secretly and mathematics clearly. Restricted to first-year students. Not eligible for CR/NCR option.', 'Not intended for students in a Mathematics Specialist or Major program.', 5, null::jsonb),
    ('MAT199H1', 'Aha! Mathematical Discovery and Creative Problem Solving', '36S', 'This course is an exploration into the creative process and use of imagination as they arise in the context of mathematical problem solving. The problems, which are all at a pre-calculus level, are chosen primarily by the criterion of aesthetic appeal, and emphasize reasoning rather than technique. Still, many of them are quite challenging, and substantial independent thinking will be required, the course is therefore appropriate for students from a variety of backgrounds and disciplines, including hard sciences. Its goal will be to hone each participant''s creativity and mathematical problem-solving skills while guiding them towards the `Aha!'' experience which accompanies independent discovery. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('MAT221H1', 'Applied Linear Algebra', '36L/12T', 'An application-oriented approach to linear algebra, based on calculations in standard Euclidean space. Systems of linear equations, matrices, Gaussian elimination, subspaces, bases, orthogonal vectors and projections. Matrix inverses, kernel and range, rank-nullity theorem. Determinants, eigenvalues and eigenvectors, Cramer''s rule, diagonalization. This course has strong emphasis on building computational skills in the area of algebra. Applications to curve fitting, economics, Markov chains and cryptography.', 'MAT223H1/  MAT223H5/  MATA22H3/  MATA23H3/  MAT224H1/  MAT224H5/  MATB24H3/  MAT240H1/  MAT240H5/ MAT185H1/ MAT188H1', 5, null::jsonb),
    ('MAT223H1', 'Linear Algebra I', '36L/12T', 'A first course on linear algebra in R^n emphasizing the interplay between algebraic and geometric perspectives. Topics include systems of equations, Gaussian elimination, representations of lines and planes, dot products, subspaces and translated subspaces, bases and change of basis, projections, the rank and nullity of a linear transformation, the rank/nullity/row space/column space of a matrix, matrix inverses, determinants, eigenvectors and eigenvalues, and matrix diagonalization. While not emphasizing proofs, this course does maintain a careful distinction between vectors and their representation in a basis as well as between matrices and linear transformations.', 'MAT223H5/  MATA22H3/  MATA23H3/  MAT224H1/  MAT224H5/  MATB24H3/  MAT240H1/  MAT240H5/  MAT247H1/  MAT247H5/ MAT185H1/ MAT188H1', 5, null::jsonb),
    ('MAT224H1', 'Linear Algebra II', '36L/12T', 'Fields, complex numbers, vector spaces over a field, linear transformations, matrix of a linear transformation, kernel, range, dimension theorem, isomorphisms, change of basis, eigenvalues, eigenvectors, diagonalizability, real and complex inner products, spectral theorem, adjoint/self-adjoint/normal linear operators, triangular form, nilpotent mappings, Jordan canonical form.', null, 5, '{"operator": "OR", "items": ["MAT221H1", "MAT223H1", "MAT223H5", "MATA22H3", "MATA23H3", "MAT240H1", "MAT240H5"]}'::jsonb),
    ('MAT235Y1', 'Multivariable Calculus', '72L', 'Parametric equations and polar coordinates. Vectors, vector functions and space curves. Differential and integral calculus of functions of several variables. Line integrals and surface integrals and classic vector calculus theorems. Examples from life sciences and physical science applications.', 'MAT235Y5/ ( MAT232H5/  MAT233H5,  MAT236H5/  MAT368H5)/ ( MATB41H3,  MATB42H3)/  MAT237Y1/ MAT291H1/ MAT294H1', 5, '{"operator": "OR", "items": ["MAT133Y1", "MAT133Y5", {"operator": "AND", "items": ["MATA32H3", "MATA33H3"]}, {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, {"operator": "AND", "items": ["MAT135H5", "MAT136H5"]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["MATA30H3", "MATA31H3"]}, {"operator": "OR", "items": ["MATA36H3", "MATA37H3"]}]}, "MAT137Y1", "MAT137Y5", {"operator": "AND", "items": ["MAT137H5", "MAT139H5"]}, "MAT157Y1", "MAT157Y5", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}]}'::jsonb),
    ('MAT237Y1', 'Multivariable Calculus with Proofs', '72L', 'Elementary topology in Euclidean space. Differential calculus of vector valued functions of a vector variable. Implicit and inverse function theorems, regular surfaces. Optimization, Lagrange multipliers, multivariable Taylor polynomials. Integral calculus with the Jordan measure. Fubini''s theorem, change of variables. Line and surface integrals. Vector calculus in two- and three-dimensions. Green''s theorem, Divergence theorem, Stokes'' theorem. Fourier series. This course is recommended for students interested in proof-based multivariable calculus with balanced emphasis between theory and applications.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT133Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, {"operator": "AND", "items": ["MAT135H5", "MAT136H5"]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["MATA30H3", "MATA31H3"]}, "MATA36H3"]}]}, {"operator": "OR", "items": ["MAT138H1", "MAT102H5", "MAT246H1"]}]}, "MAT137Y1", "MAT137Y5", {"operator": "AND", "items": ["MAT137H5", "MAT139H5"]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["MATA30H3", "MATA31H3"]}, "MATA37H3"]}, "MAT157Y1", "MAT157Y5", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}]}, {"operator": "OR", "items": ["MAT223H1", "MATA22H3", "MATA23H3", "MAT240H1", "MAT240H5"]}]}'::jsonb),
    ('MAT240H1', 'Algebra I', '36L/24T', 'A theoretical approach to: vector spaces over arbitrary fields, including C and Z_p. Subspaces, bases and dimension. Linear transformations, matrices, change of basis, similarity, determinants. Polynomials over a field (including unique factorization, resultants). Eigenvalues, eigenvectors, characteristic polynomial, diagonalization. Minimal polynomial, Cayley-Hamilton theorem.', 'MAT240H5', 5, null::jsonb),
    ('MAT244H1', 'Introduction to Ordinary Differential Equations', '36L', 'First order ordinary differential equations: Direction fields, integrating factors, separable equations, homogeneous equations, exact equations, autonomous equations, modeling. Existence and uniqueness theorem. Higher order equations: Constant coefficient equations, reduction of order, Wronskian, method of undetermined coefficients, variation of parameters. Solutions by series and integrals. First order linear systems, fundamental matrices. Non-linear equations, phase plane, stability. Applications in life and physical sciences and economics.', 'MAT242H5/  MAT244H5/  MATB44H3/  MAT212H5/  MAT258Y5/ MAT292H1/  MAT267H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT133Y1", "MAT135H1", "MAT135H5", "MATA35H3", "MATA30H3", "MATA31H3"]}, {"operator": "OR", "items": ["MAT136H1", "MAT136H5", "MATA36H3", "MATA37H3"]}]}, "MAT135Y5", "MAT137Y1", "MAT137Y5", {"operator": "AND", "items": ["MAT137H5", "MAT139H5"]}, "MAT157Y1", "MAT157Y5", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}]}, {"operator": "OR", "items": ["MAT223H1", "MATA23H3", "MAT223H5", "MAT240H1", "MAT240H5"]}]}'::jsonb),
    ('MAT245H1', 'Mathematical Methods in Data Science', '36L/24P', 'An introduction to the mathematical methods behind scientific techniques developed for extracting information from large data sets. Elementary probability density functions, conditional expectation, inverse problems, regularization, dimension reduction, gradient methods, singular value decomposition and its applications, stability, diffusion maps. Examples from applications in data science and big data.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT137Y1", "MAT157Y1"]}, {"operator": "OR", "items": ["MAT223H1", "MAT240H1"]}, {"operator": "OR", "items": ["MAT224H1", "MAT247H1"]}]}'::jsonb),
    ('MAT246H1', 'Concepts in Abstract Mathematics', '36L/12T', 'Designed to introduce students to mathematical proofs and abstract mathematical concepts. Topics may include modular arithmetic, sizes of infinite sets, and a proof that some angles cannot be trisected with straightedge and compass.', 'MAT157Y1/  MAT157Y5/  MAT157H5/  MAT159H5', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT133Y1", "MAT133Y5", {"operator": "AND", "items": ["MATA32H3", "MATA33H3"]}, {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, {"operator": "AND", "items": ["MAT135H5", "MAT136H5"]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["MATA30H3", "MATA31H3"]}, {"operator": "OR", "items": ["MATA36H3", "MATA37H3"]}]}, "MAT137Y1", "MAT137Y5", {"operator": "AND", "items": ["MAT137H5", "MAT139H5"]}]}, {"operator": "OR", "items": ["MAT223H1", "MATA22H3", "MATA23H3", "MAT240H1", "MAT240H5"]}]}'::jsonb),
    ('MAT247H1', 'Algebra II', '36L', 'A theoretical approach to real and complex inner product spaces, isometries, orthogonal and unitary matrices and transformations. The adjoint. Hermitian and symmetric transformations. Spectral theorem for symmetric and normal transformations. Polar representation theorem. Primary decomposition theorem. Rational and Jordan canonical forms. Additional topics including dual spaces, quotient spaces, bilinear forms, quadratic surfaces, multilinear algebra.', 'MAT247H5', 5, '{"operator": "OR", "items": ["MAT240H1", "MAT240H5"]}'::jsonb),
    ('MAT257Y1', 'Analysis II', '72L/48T', 'Topology of R^n; compactness, functions and continuity, extreme value theorem. Derivatives; inverse and implicit function theorems, maxima and minima, Lagrange multipliers. Integration; Fubini''s theorem, partitions of unity, change of variables. Differential forms. Manifolds in R^n; integration on manifolds; Stokes'' theorem for differential forms and classical versions. Some topics may vary year-to-year.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT157Y1", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}, "MAT157Y5"]}, {"operator": "OR", "items": ["MAT247H1", "MAT247H5"]}]}'::jsonb),
    ('MAT267H1', 'Advanced Ordinary Differential Equations', '36L/12T', 'A theoretical course on Ordinary Differential Equations. First-order equations: separable equations, exact equations, integrating factors. Variational problems, Euler-Lagrange equations. Linear equations and first-order systems. Fundamental matrices, Wronskians. Non-linear equations. Existence and uniqueness theorems. Method of power series. Elementary qualitative theory; stability, phase plane, stationary points. Oscillation theorem, Sturm comparison. Applications in mechanics, physics, chemistry, biology and economics.', 'MAT234H1/ MAT292H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT157Y1", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}, "MAT157Y5"]}, {"operator": "OR", "items": ["MAT247H1", "MAT247H5"]}]}'::jsonb),
    ('MAT271H1', 'Insights from Mathematics', '36L/6T', 'This breadth course is accessible to students with limited mathematical background. Various mathematical techniques will be illustrated with examples from humanities and social science disciplines. Some of the topics will incorporate user friendly computer explorations to give participants the feel of the subject without requiring skill at calculations. Note: This course cannot be used to satisfy requirements of program in the math department.', null, 5, null::jsonb),
    ('MAT282H1', 'Topics in Mathematics', '36L', 'A course in mathematics on a topic outside the current undergraduate offerings. For information on the specific topic to be studied and possible additional prerequisites, go to http://www.math.toronto.edu/cms/current-students-ug/', null, 5, '{"operator": "AND", "items": [{"credits": 1.0, "department": "MAT"}]}'::jsonb),
    ('MAT295H1', 'Independent Reading in Mathematics', null, 'Independent study under the direction of a faculty member. Topic must be outside undergraduate offerings. Similar workload to a 36L course. Not eligible for CR/NCR option. Completed applications for this course are due to the Math Undergraduate Program Office no later than the third day of the term that the reading course will start.', null, 5, null::jsonb),
    ('MAT296H1', 'Independent Reading in Mathematics', null, 'Independent study under the direction of a faculty member. Topic must be outside undergraduate offerings. Workload equivalent to a 36L course. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('MAT297Y1', 'Research Project in Mathematics', null, 'Independent research under the direction of a faculty member. Similar workload to a 72L course. Not eligible for CR/NCR option. Completed applications for this course are due to the Math Undergraduate Program Office no later than the third day of the term that the reading course will start.', null, 5, null::jsonb),
    ('MAT299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('MAT299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('MAT301H1', 'Groups and Symmetries', '36L', 'Congruences and fields. Permutations and permutation groups. Linear groups. Abstract groups, homomorphisms, subgroups. Symmetry groups of regular polygons and Platonic solids, wallpaper groups. Group actions, class formula. Cosets, Lagrange theorem. Normal subgroups, quotient groups. Classification of finitely generated abelian groups. Emphasis on examples and calculations.', 'MAT347Y1', 5, '{"operator": "OR", "items": ["MAT257Y1", {"operator": "AND", "items": [{"operator": "OR", "items": ["MAT224H1", "MAT247H1"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1"]}, {"operator": "OR", "items": ["MAT246H1", "MAT157Y1", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}, "MAT157Y5", "CSC236H1", "CSC240H1"]}]}, {"operator": "AND", "items": ["MAT185H1", "MAT194H1", "MAT195H1"]}]}'::jsonb),
    ('MAT309H1', 'Introduction to Mathematical Logic', '36L', 'Predicate calculus. Relationship between truth and provability; Gödel''s completeness theorem. First order arithmetic as an example of a first-order system. Gödel''s incompleteness theorem; outline of its proof. Introduction to recursive functions.', 'CSC438H1', 5, '{"operator": "OR", "items": ["MAT257Y1", {"operator": "AND", "items": [{"operator": "OR", "items": ["MAT223H1", "MATA23H3", "MAT223H5", "MAT240H1", "MAT240H5"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT235Y5", {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, {"operator": "AND", "items": ["MATB41H3", {"operator": "OR", "items": ["MATB42H3", "MATB43H3"]}]}, "MAT237Y1", "MAT237Y5"]}, {"operator": "OR", "items": ["MAT246H1", "MAT157Y1", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}, "MAT157Y5", "CSC236H1", "CSC240H1"]}]}]}'::jsonb),
    ('MAT315H1', 'Introduction to Number Theory', '36L', 'Elementary topics in number theory: arithmetic functions; polynomials over the residue classes modulo m, characters on the residue classes modulo m; quadratic reciprocity law, representation of numbers as sums of squares.', null, 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT223H1", "MATA23H3", "MAT223H5", "MAT240H1", "MAT240H5"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT235Y5", {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, {"operator": "AND", "items": ["MATB41H3", "MATB42H3"]}, "MAT237Y1", {"operator": "AND", "items": ["MATB41H3", "MATB42H3", "MATB43H3"]}, "MAT237Y5"]}, {"operator": "OR", "items": ["MAT246H1", "CSC236H1", "CSC240H1"]}]}, "MAT157Y1", "MAT157Y5", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}, "MAT247H1", "MAT247H5"]}'::jsonb),
    ('MAT327H1', 'Introduction to Topology', '36L', 'Metric spaces, topological spaces and continuous mappings; separation, compactness, connectedness. Fundamental group and covering spaces. Brouwer fixed-point theorem. Students in the math specialist program wishing to take additional topology courses are advised to obtain permission to take MAT1300H, MAT1301H.', null, 5, '{"operator": "OR", "items": ["MAT157Y1", "MAT157Y5", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["MAT237Y1", {"operator": "AND", "items": ["MATB41H3", {"operator": "OR", "items": ["MATB42H3", "MATB43H3"]}]}, "MAT237Y5"]}, "MAT246H1"]}]}'::jsonb),
    ('MAT329Y1', 'Concepts in Elementary Mathematics', '72L', 'This course is aimed at students intending to become elementary school teachers. Emphasis is placed on the formation and development of fundamental reasoning and learning skills required to understand and to teach mathematics at the elementary level. Topics may include: Problem Solving and Strategies, Sets and Elementary Logic, Numbers and Elements of Number Theory, Introductory Probability and Fundamentals of Geometry.  The course may include an optional practicum in school classrooms.', 'MAT382H5', 5, '{"operator": "AND", "items": [{"credits": 5.0, "department": null}, {"operator": "OR", "items": ["MAT137Y1", "MAT137Y5", {"operator": "AND", "items": ["MAT137H5", "MAT139H5"]}, "MAT138H1", "MAT223H1", "MAT240H1", "MAT246H1", "MAT157Y1", "MAT157Y5", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}]}]}'::jsonb),
    ('MAT332H1', 'Introduction to Graph Theory', '36L', 'This course will explore the following topics: Graphs, subgraphs, isomorphism, trees, connectivity, Euler and Hamiltonian properties, matchings, vertex and edge colourings, planarity, network flows and strongly regular graphs. Participants will be encouraged to use these topics and execute applications to such problems as timetabling, tournament scheduling, experimental design and finite geometries.', null, 5, '{"operator": "OR", "items": ["MAT224H1", "MATB24H3", "MAT224H5", "MAT247H1", "MAT247H5"]}'::jsonb),
    ('MAT334H1', 'Complex Variables', '36L', 'Theory of functions of one complex variable, analytic and meromorphic functions. Cauchy''s theorem, residue calculus, conformal mappings, introduction to analytic continuation and harmonic functions.', 'MAT354H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT223H1", "MATA23H3", "MAT223H5", "MAT240H1", "MAT240H5"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT235Y5", {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, {"operator": "AND", "items": ["MATB41H3", "MATB42H3"]}, "MAT237Y1", {"operator": "AND", "items": ["MATB41H3", "MATB42H3", "MATB43H3"]}, "MAT237Y5", "MAT257Y1"]}]}'::jsonb),
    ('MAT335H1', 'Chaos, Fractals and Dynamics', '36L', 'An elementary introduction to a modern and fast-developing area of mathematics. One-dimensional dynamics: iterations of quadratic polynomials. Dynamics of linear mappings, attractors. Bifurcation, Henon map, Mandelbrot and Julia sets. History and applications.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT137Y1", {"operator": "AND", "items": ["MATA30H3", "MATA31H3", "MATA37H3"]}, "MAT137Y5", {"operator": "AND", "items": ["MAT137H5", "MAT139H5"]}, "MAT157Y1", "MAT157Y5", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}, "MAT235Y1", "MAT235Y5", {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, {"operator": "AND", "items": ["MATB41H3", "MATB42H3"]}, "MAT237Y1", {"operator": "AND", "items": ["MATB41H3", "MATB42H3", "MATB43H3"]}, "MAT237Y5"]}, {"operator": "OR", "items": ["MAT223H1", "MATA23H3", "MAT223H5", "MAT240H1", "MAT240H5"]}]}'::jsonb),
    ('MAT336H1', 'Elements of Analysis', '36L/12T', 'This course provides the foundations of analysis and rigorous calculus for students who will take subsequent courses where these mathematical concepts are central of applications, but who have only taken courses with limited proofs. Topics include topology of Rn, implicit and inverse function theorems and rigorous integration theory.', 'MAT257Y1/  MAT337H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT223H1", "MATA23H3", "MAT223H5", "MAT240H1", "MAT240H5"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT235Y5", {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, {"operator": "AND", "items": ["MATB41H3", "MATB42H3"]}, "MAT237Y1", {"operator": "AND", "items": ["MATB41H3", "MATB42H3", "MATB43H3"]}, "MAT237Y5", {"operator": "AND", "items": ["MAT185H1", {"operator": "OR", "items": ["MAT195H1", "ESC195H1"]}]}]}]}'::jsonb),
    ('MAT337H1', 'Introduction to Real Analysis', '36L', 'Construction of Real Numbers. Metric spaces; compactness and connectedness. Sequences and series of functions, power series; modes of convergence. Interchange of limiting processes; differentiation of integrals. Function spaces; Weierstrass approximation; Fourier series. Contraction mappings; existence and uniqueness of solutions of ordinary differential equations. Countability; Cantor set; Hausdorff dimension.', 'MAT357H1/  MAT378H5', 5, '{"operator": "OR", "items": ["MAT257Y1", {"operator": "AND", "items": [{"operator": "OR", "items": ["MAT224H1", "MATA24H3", "MAT224H5", "MAT247H1", "MAT247H5"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT235Y5", {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, {"operator": "AND", "items": ["MATB41H3", {"operator": "OR", "items": ["MATB42H3", "MATB43H3"]}]}, "MAT237Y1", "MAT237Y5"]}, {"operator": "OR", "items": ["MAT246H1", "MAT157Y1"]}]}]}'::jsonb),
    ('MAT344H1', 'Introduction to Combinatorics', '36L', 'Basic counting principles, generating functions, permutations with restrictions. Fundamentals of graph theory with algorithms; applications (including network flows). Combinatorial structures including block designs and finite geometries.', null, 5, '{"operator": "OR", "items": ["MAT223H1", "MATA23H3", "MAT223H5", "MAT240H1", "MAT240H5"]}'::jsonb),
    ('MAT347Y1', 'Groups, Rings and Fields', '72L/24T', 'Groups, subgroups, quotient groups, Sylow theorems, Jordan-Hölder theorem, finitely generated abelian groups, solvable groups. Rings, ideals, Chinese remainder theorem; Euclidean domains and principal ideal domains: unique factorization. Noetherian rings, Hilbert basis theorem. Finitely generated modules. Field extensions, algebraic closure, straight-edge and compass constructions. Galois theory, including insolvability of the quintic.', null, 5, '{"operator": "OR", "items": ["MAT257Y1", "MAT247H1", "MAT247H5"]}'::jsonb),
    ('MAT351Y1', 'Partial Differential Equations', '72L', 'This is a first course in Partial Differential Equations, intended for Mathematics students with interests in analysis, mathematical physics, geometry, and optimization. The examples to be discussed include first-order equations, harmonic functions, the diffusion equation, the wave equation, Schrodinger''s equation, and eigenvalue problems. In addition to the classical representation formulas for the solutions of these equations, there are techniques that apply more broadly: the notion of well-posedness, the method of characteristics, energy methods, maximum and comparison principles, fundamental solutions, Green''s functions, Duhamel''s principle, Fourier series, the min-max characterization of eigenvalues, Bessel functions, spherical harmonics, and distributions. Nonlinear phenomena such as shock waves and solitary waves are also introduced.', 'APM351Y1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT257Y1", "MAT237Y1"]}, "MAT267H1"]}'::jsonb),
    ('MAT354H1', 'Complex Analysis I', '36L', 'Complex numbers, the complex plane and Riemann sphere, Möbius transformations, elementary functions and their mapping properties, conformal mapping, holomorphic functions, Cauchy''s theorem and integral formula. Taylor and Laurent series, maximum modulus principle, Schwarz'' lemma, residue theorem and residue calculus.', null, 5, '{"operator": "OR", "items": ["MAT257Y1", {"operator": "AND", "items": ["MAT237Y1", "MAT327H1"]}]}'::jsonb),
    ('MAT357H1', 'Foundations of Real Analysis', '36L', 'Function spaces; Arzela-Ascoli theorem, Weierstrass approximation theorem, Fourier series. Introduction to Banach and Hilbert spaces; contraction mapping principle, fundamental existence and uniqueness theorem for ordinary differential equations. Lebesgue integral; convergence theorems, comparison with Riemann integral, L^p spaces. Applications to probability.', 'MAT438H5', 5, '{"operator": "OR", "items": ["MAT257Y1", {"operator": "AND", "items": ["MAT237Y1", "MAT327H1"]}]}'::jsonb),
    ('MAT363H1', 'Geometry of Curves and Surfaces', '36L', 'Curves and surfaces in 3-spaces. Frenet formulas. Curvature and geodesics. Gauss map. Minimal surfaces. Gauss-Bonnet theorem for surfaces. Surfaces of constant curvature.', null, 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT224H1", "MATB24H3", "MAT224H5", "MAT247H1", "MAT247H5"]}, {"operator": "OR", "items": ["MAT237Y1", {"operator": "AND", "items": ["MATB41H3", "MATB42H3", "MATB43H3"]}, "MAT237Y5", "MAT257Y1"]}]}, {"operator": "AND", "items": ["MAT185H1", "MAT194H1", "MAT195H1", "AER210H1"]}]}'::jsonb),
    ('MAT367H1', 'Differential Geometry', '36L', 'Manifolds, partitions of unity, submersions and immersions, vector fields, vector bundles, tangent and cotangent bundles, foliations and Frobenius'' theorem, multilinear algebra, differential forms, Stokes'' theorem, Poincare-Hopf theorem.', null, 5, '{"operator": "OR", "items": ["MAT257Y1", {"operator": "AND", "items": [{"operator": "OR", "items": ["MAT224H1", "MAT247H1"]}, "MAT237Y1", {"operator": "OR", "items": ["MAT246H1", "MAT157Y1", "MAT157Y5", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}]}]}]}'::jsonb),
    ('MAT370H1', 'Introduction to Mathematical Probability', '36L/12T', 'A rigorous introduction to the basic concepts of probability without measure theory. Random variables and their distributions, Independence, Limit theorems, Conditional Probability, Markov chains', 'MAT377H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT224H1", "MAT224H5"]}, {"operator": "OR", "items": ["MAT235Y1", {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, "MAT237Y1", "MAT257Y1"]}, "MAT246H1"]}'::jsonb),
    ('MAT377H1', 'Mathematical Probability Theory', '36L/12T', 'This course introduces students to various topics in mathematical probability theory. Topics include basic concepts (such as probability, random variables, expectations, conditional probability) from a mathematical point of view, examples of distributions and stochastic processes and their properties, convergence results (such as the law of large numbers, central limit theorem, random series, etc.), various inequalities, and examples of applications of probabilistic ideas beyond statistics (for example, in geometry and computer science).', 'MAT370H1,  STA347H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT247H1", "MAT247H5"]}, {"operator": "OR", "items": ["MAT257Y1", {"operator": "AND", "items": ["MAT237Y1", "MAT327H1"]}]}]}'::jsonb),
    ('MAT382H1', 'Topics in Mathematics', '36L', 'A course in mathematics on a topic outside the current undergraduate offerings. For information on the specific topic to be studied and possible additional prerequisites, go to http://www.math.toronto.edu/cms/current-students-ug/', null, 5, '{"operator": "AND", "items": [{"credits": 2.5, "department": null}]}'::jsonb),
    ('MAT390H1', 'History of Mathematics up to 1700', '24L/12T', 'A survey of ancient, medieval, and early modern mathematics with emphasis on historical issues.', 'HPS309H1/  HPS310Y1/  HPS390H1', 5, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('MAT391H1', 'History of Mathematics after 1700', '24L/12T', 'A survey of the development of mathematics from 1700 to the present with emphasis on technical development.', 'HPS309H1/  HPS310H1/  HPS391H1', 5, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('MAT395H1', 'Independent Reading in Mathematics', null, 'Independent reading under the direction of a faculty member. Topic must be outside current undergraduate offerings. Similar workload to a 36L course. Not eligible for CR/NCR option. Completed applications for this course are due to the Math Undergraduate Program Office no later than the third day of the term that the reading course will start.', null, 5, null::jsonb),
    ('MAT396H1', 'Independent Reading in Mathematics', null, 'Independent study under the direction of a faculty member. Topic must be outside undergraduate offerings. Similar workload to a 36L course. Not eligible for CR/NCR option. Completed applications for this course are due to the Math Undergraduate Program Office no later than the third day of the term that the reading course will start.', null, 5, null::jsonb),
    ('MAT397Y1', 'Research Project in Mathematics', null, 'Independent research under the direction of a faculty member. Workload similar to a 72L course. Not eligible for CR/NCR option. Completed applications for this course are due to the Math Undergraduate Program Office no later than the third day of the term that the reading course will start.', null, 5, null::jsonb),
    ('MAT398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('MAT398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('MAT399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('MAT399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('MAT401H1', 'Polynomial Equations and Fields', '36L', 'Commutative rings; quotient rings. Construction of the rationals. Polynomial algebra. Fields and Galois theory: Field extensions, adjunction of roots of a polynomial. Constructibility, trisection of angles, construction of regular polygons. Galois groups of polynomials, in particular cubics, quartics. Insolvability of quintics by radicals.', 'MAT347Y1', 5, '{"operator": "AND", "items": ["MAT301H1"]}'::jsonb),
    ('MAT402H1', 'Classical Geometries', '36L', 'Euclidean and non-Euclidean plane and space geometries. Real and complex projective space. Models of the hyperbolic plane. Connections with the geometry of surfaces.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT224H1", "MAT247H1"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}]}'::jsonb),
    ('MAT403H1', 'Classical Geometries II', '36L/12T', 'This course is the second part of the "Classical Geometries"  MAT402H1 course. It is mainly dedicated to detailed study of classical real projective geometry and projective geometry over other fields. It is also devoted to the study of spherical and elliptic geometry.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}, {"operator": "OR", "items": ["MAT301H1", "MAT347Y1"]}]}'::jsonb),
    ('MAT409H1', 'Set Theory', '36L', 'Set theory and its relations with other branches of mathematics. ZFC axioms. Ordinal and cardinal numbers. Reflection principle. Constructible sets and the continuum hypothesis. Introduction to independence proofs. Topics from large cardinals, infinitary combinatorics and descriptive set theory. Joint undergraduate/graduate course -  MAT409H1/MAT1404H', null, 5, '{"operator": "AND", "items": ["MAT357H1"]}'::jsonb),
    ('MAT415H1', 'Algebraic Number Theory', '36L', 'A selection from the following: finite fields; global and local fields; valuation theory; ideals and divisors; differents and discriminants; ramification and inertia; class numbers and units; cyclotomic fields; Diophantine equations.  Joint undergraduate/graduate course -  MAT415H1/MAT1200H', null, 5, '{"operator": "AND", "items": ["MAT347Y1"]}'::jsonb),
    ('MAT417H1', 'Analytic Number Theory', '36L', 'A selection from the following: distribution of primes, especially in arithmetic progressions and short intervals; exponential sums; Hardy-Littlewood and dispersion methods; character sums and L-functions; the Riemann zeta-function; sieve methods, large and small; Diophantine approximation, modular forms. Joint undergraduate/graduate course -  MAT417H1/MAT1202H', null, 5, '{"operator": "OR", "items": ["MAT334H1", "MAT354H1"]}'::jsonb),
    ('MAT425H1', 'Differential Topology', '36L', 'Smooth manifolds, Sard''s theorem and transversality. Morse theory. Immersion and embedding theorems. Intersection theory. Borsuk-Ulam theorem. Vector fields and Euler characteristic. Hopf degree theorem. Additional topics may vary.', null, 5, '{"operator": "AND", "items": ["MAT257Y1", "MAT327H1"]}'::jsonb),
    ('MAT436H1', 'Introduction to Linear Operators', '36L', 'The course will survey the branch of mathematics developed (in its abstract form) primarily in the twentieth century and referred to variously as functional analysis, linear operators in Hilbert space, and operator algebras, among other names (for instance, more recently, to reflect the rapidly increasing scope of the subject, the phrase non-commutative geometry has been introduced). The intention will be to discuss a number of the topics in Pedersen''s textbook Analysis Now. Students will be encouraged to lecture on some of the material, and also to work through some of the exercises in the textbook (or in the suggested reference books). Joint undergraduate/graduate course -  MAT436H1/MAT1011H', null, 5, '{"operator": "AND", "items": [{"credits": 5.0, "department": "MAT"}, {"operator": "OR", "items": ["MAT224H1", "MAT247H1"]}, {"operator": "OR", "items": ["MAT237Y1", "MAT257Y1"]}]}'::jsonb),
    ('MAT437H1', 'K-Theory and C* Algebras', '36L', 'The theory of operator algebras was begun by John von Neumann eighty years ago. In one of the most important innovations of this theory, von Neumann and Murray introduced a notion of equivalence of projections in a self-adjoint algebra (*-algebra) of Hilbert space operators that was compatible with addition of orthogonal projections (also in matrix algebras over the algebra), and so gave rise to an abelian semigroup, now referred to as the Murray-von Neumann semigroup. Later, Grothendieck in geometry, Atiyah and Hirzebruch in topology, and Serre in the setting of arbitrary rings (pertinent for instance for number theory), considered similar constructions. The enveloping group of the semigroup considered in each of these settings is now referred to as the K-group (Grothendieck''s terminology), or as the Grothendieck group. Among the many indications of the depth of this construction was the discovery of Atiyah and Hirzebruch that Bott periodicity could be expressed in a simple way using the K-group. Also, Atiyah and Singer famously showed that K-theory was important in connection with the Fredholm index. Partly because of these developments, K-theory very soon became important again in the theory of operator algebras. (And in turn, operator algebras became increasingly important in other branches of mathematics.) The purpose of this course is to give a general, elementary, introduction to the ideas of K-theory in the operator algebra context. (Very briefly, K-theory generalizes the notion of dimension of a vector space.) The course will begin with a description of the method (K-theoretical in spirit) used by Murray and von Neumann to give a rough initial classification of von Neumann algebras (into types I, II, and III). It will centre around the relatively recent use of K-theory to study Bratteli''s approximately finite-dimensional C*-algebras---both to classify them (a result that can be formulated and proved purely algebraically), and to prove that the class of these C*-algebras---what Bratteli called AF algebras---is closed under passing to extensions (a result that uses the Bott periodicity feature of K-theory). Students will be encouraged to prepare oral or written reports on various subjects related to the course, including basic theory and applications. Joint undergraduate/graduate course -  MAT437H1/MAT1016H', null, 5, '{"operator": "AND", "items": [{"credits": 5.0, "department": "MAT"}, {"operator": "OR", "items": ["MAT224H1", "MAT247H1"]}, {"operator": "OR", "items": ["MAT237Y1", "MAT257Y1"]}]}'::jsonb),
    ('MAT445H1', 'Representation Theory', '36L', 'A selection of topics from: Representation theory of finite groups, topological groups and compact groups. Group algebras. Character theory and orthogonality relations. Weyl''s character formula for compact semisimple Lie groups. Induced representations. Structure theory and representations of semisimple Lie algebras. Determination of the complex Lie algebras. Joint undergraduate/graduate -  MAT445H1/MAT1196H', null, 5, '{"operator": "AND", "items": ["MAT347Y1"]}'::jsonb),
    ('MAT448H1', 'Introduction to Commutative Algebra and Algebraic Geometry', '36L', 'Basic notions of algebraic geometry, with emphasis on commutative algebra or geometry according to the interests of the instructor. Algebraic topics: localization, integral dependence and Hilbert''s Nullstellensatz, valuation theory, power series rings and completion, dimension theory. Geometric topics: affine and projective varieties, dimension and intersection theory, curves and surfaces, varieties over the complex numbers. This course will be offered in alternating years. Joint undergraduate/graduate course -  MAT448H1/MAT1155H', null, 5, '{"operator": "AND", "items": ["MAT347Y1"]}'::jsonb),
    ('MAT449H1', 'Algebraic Curves', '36L', 'Projective geometry. Curves and Riemann surfaces. Algebraic methods. Intersection of curves; linear systems; Bezout''s theorem. Cubics and elliptic curves. Riemann-Roch theorem. Newton polygon and Puiseux expansion; resolution of singularities. This course will be offered in alternating years. Joint undergraduate/graduate course -  MAT449H1/MAT1194H', null, 5, '{"operator": "AND", "items": ["MAT347Y1", "MAT354H1"]}'::jsonb),
    ('MAT454H1', 'Complex Analysis II', '36L', 'Harmonic functions, Harnack''s principle, Poisson''s integral formula and Dirichlet''s problem. Infinite products and the gamma function. Normal families and the Riemann mapping theorem. Analytic continuation, monodromy theorem and elementary Riemann surfaces. Elliptic functions, the modular function and the little Picard theorem. Joint undergraduate/graduate course -  MAT454H1/MAT1002H', null, 5, '{"operator": "AND", "items": ["MAT354H1"]}'::jsonb),
    ('MAT457H1', 'Advanced Real Analysis I', '36L', 'Lebesgue measure and integration; convergence theorems, Fubini''s theorem, Lebesgue differentiation theorem, abstract measures, Caratheodory theorem, Radon-Nikodym theorem. Hilbert spaces, orthonormal bases, Riesz representation theorem, compact operators, L^p spaces, Hölder and Minkowski inequalities. Joint undergraduate/graduate course -  MAT457H1/MAT1000H', 'MAT457Y1', 5, '{"operator": "AND", "items": ["MAT357H1"]}'::jsonb),
    ('MAT458H1', 'Advanced Real Analysis II', '36L', 'Fourier series and transform, convergence results, Fourier inversion theorem, L^2 theory, estimates, convolutions. Banach spaces, duals, weak topology, weak compactness, Hahn-Banach theorem, open mapping theorem, uniform boundedness theorem. Joint undergraduate/graduate course -  MAT458H1/MAT1001H', 'MAT457Y1', 5, '{"operator": "AND", "items": ["MAT457H1"]}'::jsonb),
    ('MAT461H1', 'Hamiltonian Mechanics', '36L', 'This course focuses on key notions of classical mechanics: Newton equations, variational principles, Lagrangian formulation and Euler-Lagrange equations, the motion in a central force, the motion of a rigid body, small oscillations, Hamiltonian formulation, canonical transformations, Hamilton-Jacobi theory, action-angle variables, and integrable systems.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT244H1", "MAT267H1"]}, {"operator": "OR", "items": ["MAT337H1", "MAT367H1"]}, {"operator": "OR", "items": ["APM346H1", "MAT351Y1"]}]}'::jsonb),
    ('MAT464H1', 'Riemannian Geometry', '36L', 'Riemannian metrics. Levi-Civita connection. Geodesics. Exponential map. Second fundamental form. Complete manifolds and Hopf-Rinow theorem. Curvature tensors. Ricci curvature and scalar curvature. Spaces of constant curvature. Joint undergraduate/graduate course -  MAT464H1/MAT1342H', null, 5, '{"operator": "AND", "items": ["MAT367H1"]}'::jsonb),
    ('MAT475H1', 'Problem Solving Seminar', null, 'This course addresses the question: How do you attack a problem the likes of which you have never seen before? Students will apply Polya''s principles of mathematical problem solving, draw upon their previous mathematical knowledge, and explore the creative side of mathematics in solving a variety of interesting problems and explaining those solutions to others.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT224H1", "MAT247H1"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}, {"credits": 1.0, "department": null}]}'::jsonb),
    ('MAT477H1', 'Seminar in Mathematics', null, 'Seminar in an advanced topic. Content will generally vary from semester to semester. Student presentations are required.', null, 5, '{"operator": "AND", "items": ["MAT347Y1", "MAT354H1", "MAT357H1"]}'::jsonb),
    ('MAT478H1', 'Seminar in Mathematics', null, 'Seminar in an advanced topic. Content will generally vary from semester to semester. Student presentations are required.', null, 5, '{"operator": "AND", "items": ["MAT347Y1", "MAT354H1", "MAT357H1"]}'::jsonb),
    ('MAT482H1', 'Topics in Mathematics', '36L', 'A course in mathematics on a topic outside the current undergraduate offerings. For information on the specific topic to be studied and possible additional prerequisites, go to http://www.math.toronto.edu/cms/current-students-ug/. Joint undergraduate/graduate course -  MAT482H1/MAT1901H', null, 5, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}]}'::jsonb),
    ('MAT483H1', 'Topics in Mathematics', '36L', 'A course in mathematics on a topic outside the current undergraduate offerings. For information on the specific topic to be studied and possible additional prerequisites, go to http://www.math.toronto.edu/cms/current-students-ug/.', null, 5, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}]}'::jsonb),
    ('MAT495H1', 'Independent Reading in Mathematics', null, 'Independent study under the direction of a faculty member. Topic must be outside undergraduate offerings. Workload equivalent to a 36L course. Not eligible for CR/NCR option. Completed applications for this course are due to the Math Undergraduate Program Office no later than the third day of the term that the reading course will start.', null, 5, null::jsonb),
    ('MAT496H1', 'Independent Reading in Mathematics', null, 'Independent study under the direction of a faculty member. Topic must be outside undergraduate offerings. Workload equivalent to a 36L course. Not eligible for CR/NCR option. Completed applications for this course are due to the Math Undergraduate Program Office no later than the third day of the term that the reading course will start.', null, 5, null::jsonb),
    ('MAT497Y1', 'Research Project in Mathematics', null, 'Independent research under the direction of a faculty member. Not eligible for CR/NCR option. Similar workload to a 72L course. Completed applications for this course are due to the Math Undergraduate Program Office no later than the third day of the term that the reading course will start.', null, 5, null::jsonb),
    ('MAT499Y1', 'Readings in Mathematics', null, 'Independent study under the direction of a faculty member. Topic must be outside undergraduate offerings. Workload equivalent to a 72L course. Not eligible for CR/NCR option. Completed applications for this course are due to the Math Undergraduate Program Office no later than the third day of the term that the reading course will start.', null, 5, null::jsonb),
    ('MCS223H1', 'Signs, Meanings, and Culture', '24S', 'This course will introduce the principles of semiotic thought, applying them to the study of language, social organization, myth, and material culture. Examples may be drawn from everyday life as well as from classical and popular art and music, and from screen culture.', 'VIC223Y1', 2, null::jsonb),
    ('MCS224H1', 'Approaches to Material Culture', '12P/24S', 'This course is about things - the everyday objects of past and present cultures. It examines the meanings people have invested in objects and how those meanings have changed over time. Using interdisciplinary approaches, students investigate objects found in homes, retail spaces, cities, art galleries and museums in order to develop new understandings of the objects that structure their daily lives and their material world.', 'VIC224H1,  VIC224Y1,  MCS224Y1', 2, null::jsonb),
    ('MCS225Y1', 'A History of the World in Objects and Signs', '24P/48S', 'Through a multidisciplinary approach, this course opens new perspectives on the history of artifacts, the evolution of a world of things and signs, and the meanings of material culture. Lectures and tutorials are supplemented by hands-on exercises in museums and local communities.', 'VIC225Y1', 3, null::jsonb),
    ('MCS226H1', 'The Materiality of Magic: Sorcery, Spells, Devotion, and Divination', '24S', 'Magic is a wide field of study comprising spirituality, mysticism, paranormal events, the occult, and other unexplained phenomena. This course aims to (re-)materialize magic and to anchor it in the physical objects that have played an indispensable role in the practice and performance of ceremonies and rituals from Prehistory to the present day. Students will apply theoretical lenses to understand how objects – relics, icons, effigies, charms, amulets – are transformed through, and become instruments of, rituals that control, placate, or please the supernatural world. The course brings together a range of disciplines and perspectives to contextualize and to challenge our perception of the material manifestations of magic.', null, 2, null::jsonb),
    ('MCS320H1', 'Semiotics of Visual Art', '24L', 'Theories and models of applied semiotics: analysis of sign systems as articulated in various forms of artistic and cultural production.', 'VIC320H1', 1, '{"operator": "OR", "items": ["MCS223H1", "VIC223Y1"]}'::jsonb),
    ('MCS322H1', 'Topics in Semiotics', '24S', 'An in-depth examination of some aspect of semiotic theory or practice. Content in any given year depends on instructor. Not offered every year. Please refer to course website for more information: https://vic.utoronto.ca/academic-programs/special-topics-courses/mcs322h', null, 1, '{"operator": "AND", "items": ["MCS223H1"]}'::jsonb),
    ('MCS323H1', 'Theories of the Sign', '24S', 'Theories of signification studied with a focus on major works in the semiotics of modern and contemporary culture.', 'VIC323Y1', 1, '{"operator": "OR", "items": ["MCS223H1", "VIC223Y1"]}'::jsonb),
    ('MCS325H1', 'Media Semiotics', '24L', 'This course will deal with media semiotics, both in the traditional sense of the study of meanings in all media (from print to digital) and in how new digital media are changing the nature of signification and communication. The course will look at the usage of semiotics to study how meaning is negotiated in interactive media versus the older and still extant one-way media (print and radio, for example). The course will utilize actual media materials (comic books, television programs, text messages, and so on) on which semiotic analysis can be conducted.', 'VIC325H1', 1, '{"operator": "OR", "items": ["MCS223H1", "VIC223Y1"]}'::jsonb),
    ('MCS326H1', 'The Material Culture of Food', null, 'This course explores the material cultures which form around food and foodways in contemporary culture. It looks at foods as objects of production and consumption and at the material landscapes (culinary tools, the geography of the kitchen and restaurant, the archives - recipes, cookbooks, menus - that home cooks or chefs use) in order to "expose" the social, cultural and political dimensions of cooking, entertaining and eating.', 'VIC326H1;  VIC229H1 (Special Topics in Material Culture: The Material Culture of Food), offered in Winter 2016', 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('MCS327H1', 'Digital Material Culture', '24S', 'This course explores the materiality of digital objects, from image and music files to digital documents to video games and other software, and considers their status as material culture. It involves the primary study of digital objects and also considers the technological infrastructures, cultural contexts, and signifying systems in which they are produced, circulated, and interpreted.', 'VIC327H1', 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('MCS328H1', 'Materializing Cultural Identities', '24S', 'Students examine the expression of cultural identities in objects. Students are taught to think critically about the construction, use, display, and exchange of objects with significance for cultural identity. In addition to lectures and discussions, students participate in guided visits to sites – everyday, ritual, institutional – where negotiation of identity through objects occurs.', 'VIC328H1', 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('MCS329H1', 'Practicum in Material Culture', null, 'A practical or experiential learning opportunity under the supervision of a faculty member, normally at a museum, art gallery or other cultural agency (as approved by the supervisor). This course is restricted to students enrolled in the Material Culture and Semiotics program. Not eligible for CR/NCR option.', 'VIC329H1', null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["MCS224H1", "MCS225Y1"]}]}'::jsonb),
    ('MCS329Y1', 'Practicum in Material Culture', null, 'A practical or experiential learning opportunity under the supervision of a faculty member, normally at a museum, art gallery or other cultural agency (as approved by the supervisor). This course is restricted to students enrolled in the Material Culture and Semiotics program. Not eligible for CR/NCR option.', 'VIC329Y1', null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["MCS224H1", "MCS225Y1"]}]}'::jsonb),
    ('MCS330H1', 'Topics in Material Culture', '24S', 'An in-depth examination of some aspect of Material Culture theory or practice. Content in any given year depends on instructor. Not offered every year. Please refer to course website for more information: https://vic.utoronto.ca/academic-programs/special-topics-courses/mcs330h', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('MCS331H1', 'The Materiality of Information', '24S', 'This course looks at the material culture of information from a global historical perspective. It explores the roots of our modern understanding of information through a series of case studies and practical activities like learning to write cuneiform characters on clay tablets, and cutting quill pens. These practical activities are framed by discussions of the material and cultural factors that influenced the development of information technologies throughout history.', 'MCS330H1 (Topics in Material Culture: Materiality of Information), offered in Fall 2023', 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('MCS336H1', 'Material Culture of Wine', '24L', 'This course explores the material cultures of wine in historical and contemporary contexts. Today, the world produces almost 300 million hectolitres of wine annually and wine is produced and consumed on every inhabited continent. It''s a global industry worth more than 30 billion dollars every year and wine is traditionally valuable as a tangible expression of family, national, and regional identity. Wine is an edible, material commodity, an expression of class status, and considered by many as an integral part of a meal. Through weekly tastings of wine from across the globe, this course considers wine as vital objects of production and consumption and as material landscapes (technologies of transport and vinification, the nature of wine service, and environmental engagements) in order to explore the social, cultural, and political dimensions of drink on a global scale. Students must be of legal drinking age, and will have the option of tasting c. 2-5 oz of wine per class. This course has a mandatory Materials Fee to cover the cost of wine. The fee will be included on students'' ACORN invoice. See the Victoria College website for the current amount.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('MCS373H1', 'Materialities of Music', '24L', 'Music is often understood as the most ephemeral and transcendent of the fine arts, even if that means overlooking the physical realities of music''s production and dissemination. We will examine these materialities here, from paper and technologies of print, through to instruments for making and studying sound, and architectural spaces for its market circulation; we will see how music and its instruments provided the raw material for the emergence of a nineteenth-century science of acoustics.', 'VIC373H1', 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('MCS429H1', 'Advanced Topics in Material Culture, Information Systems and Meaning-Making', '24S', 'Content varies depending on instructor. Selected issues are examined in depth and at an advanced level. Please refer to course website for more information: https://vic.utoronto.ca/academic-programs/special-topics-courses/mcs429h', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["MCS224Y1", "MCS225Y1"]}]}'::jsonb),
    ('MCS444H1', 'Themes in Material Culture', '24S', 'This fourth year seminar, required for students pursuing a minor in material culture, will have opportunities to explore themes in material culture studies, museum exhibitions and collections as well as processes of object analysis in greater depth and at an advanced level. Specific topics and research projects will vary according to the interests and specialties of course instructors and students. Please see the Victoria College website for the current topics: https://vic.utoronto.ca/academic-programs/special-topics-courses/mcs444h', 'VIC444H1', 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["MCS224Y1", "MCS225Y1"]}]}'::jsonb),
    ('MGR100H1', 'Introductory Modern Greek', '24L', 'This course is designed for absolute beginners in the Modern Greek language. The overall goal is to facilitate understanding and use of familiar everyday expressions and phrases aimed at the satisfaction of basic communicative needs. Students will familiarize themselves with the Modern Greek alphabet, pronunciation and grammatical rules. No previous knowledge of Modern Greek required.', 'Students who have completed High School in Greece or a Grade 12 Modern Greek language credit.', 1, null::jsonb),
    ('MGR101H1', 'Elementary Modern Greek', '24L', 'This course builds on  MGR100H1 and aims to develop competence in the Modern Greek language at the basic level. Students will attain elementary proficiency in the spoken and written language by familiarizing themselves with a variety of grammatical and syntax structures while continuing to enrich their vocabulary. Emphasis will be placed on reading and conversational skills while students are expected to write short descriptive paragraphs.', 'Students who have completed High School in Greece or a Grade 12 Modern Greek language credit.', 1, '{"operator": "AND", "items": ["MGR100H1"]}'::jsonb),
    ('MGR245Y1', 'Intermediate Modern Greek', '78S', 'A course designed for students with some command of the language: vocabulary building; study of grammar and syntax; compositional skills leading to the study of a prose literary work.', null, 1, null::jsonb),
    ('MGR300H1', 'Advanced Modern Greek I', '24L', 'This course builds on the Intermediate level background knowledge to prepare students as independent users of the Modern Greek language. In order to attain conversational fluency and communicate effectively and accurately with native Greek language speakers, students will practice on reading and interpreting magazine and newspaper articles on various topics as well as applying more complex grammatical and syntax rules to write essays on assigned subjects.', null, 1, '{"operator": "AND", "items": ["MGR245Y1"]}'::jsonb),
    ('MGR301H1', 'Advanced Modern Greek II', '24L', 'The aim of this course is to facilitate fluency both in spoken and written Modern Greek. Proficiency at this level will be attained through familiarization with various texts and genres including a Modern Greek literature anthology and selected academic articles. Emphasis will be placed on writing which will lead to the production of a short research paper in Modern Greek.', null, 1, '{"operator": "AND", "items": ["MGR300H1"]}'::jsonb),
    ('MGT100H1', 'Fundamentals of Management', '24L', 'Introduction to management and its subdisciplines. Themes include business in a Canadian context, the nature of corporations, corporate governance, organizational behavior, operations, and strategy. Not open to Rotman Commerce students.', 'RSM100H1,  RSM100Y1', 3, null::jsonb),
    ('MGT201H1', 'Fundamentals of Financial Accounting', '24L', 'Introduction to financial reporting and analysis that is used by companies to organize and evaluate data in light of their organization''s goal. Emphasis is on decision-making and interpretation of financial statements and how they can be used to plan a firm''s overall business activities through the use of real-world companies. Not open to Rotman Commerce students.', 'RSM219H1', 3, null::jsonb),
    ('MGT230H1', 'Introduction to Financial Markets', '24L', 'This course is an introduction to financial securities and financial markets. It discusses the structure and function of financial markets, financial institutions and market participants, as well as some tools for market analysis. The objective of the course is to provide students with basic knowledge required to understand the nature of financial securities and markets and current financial issues. Not open to Rotman Commerce students.', 'RSM230H1', 3, null::jsonb),
    ('MGT250H1', 'Fundamentals of Marketing', '24L', 'This course is designed to introduce students to the key principles of marketing. After taking the course, students will understand the marketing planning process, including segmentation, targeting, positioning, marketing analysis, and strategy. In addition, students will be able to make basic marketing decisions to profitably satisfy customer needs and execute marketing strategies including product development, pricing, distribution and communications. Not open to Rotman Commerce students.', 'RSM250H1', 2, null::jsonb),
    ('MGT295Y0', 'Special Topics', '48L', 'The area of concentration and location depend on the instructor teaching the course. (Offered only during the Summer Session through the Summer Abroad Program). Contact Rotman Commerce for details.', null, null, null::jsonb),
    ('MGT296Y0', 'Special Topics', '48L', 'The area of concentration and location depend on the instructor teaching the course. (Offered only during the Summer Session through the Summer Abroad Program). Contact Rotman Commerce for details.', null, null, null::jsonb),
