    ('MGT302H1', 'Independent Study', null, 'Open when a faculty member is willing and able to supervise. Students must obtain the approval of the Director of Rotman Commerce and the supervising faculty member before enrolling. Enrolment is restricted to students not in a Rotman Commerce program. Consult the Rotman Commerce Office for details. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
